'use client';

import * as React from 'react';
import { clsx, type ClassValue } from 'clsx';
import { twMerge } from 'tailwind-merge';

function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

export interface CardItem {
  id: string | number;
  title: string;
  description: string;
  imgSrc: string;
  icon: React.ReactNode;
  linkHref?: string;
}

export interface ExpandingCardsProps extends React.HTMLAttributes<HTMLUListElement> {
  items: CardItem[];
  defaultActiveIndex?: number;
}

export const ExpandingCards = React.forwardRef<HTMLUListElement, ExpandingCardsProps>(
  ({ className, items, defaultActiveIndex = 0, ...props }, ref) => {
    const [activeIndex, setActiveIndex] = React.useState<number | null>(defaultActiveIndex);
    const [isDesktop, setIsDesktop] = React.useState(true);

    React.useEffect(() => {
      const handleResize = () => {
        setIsDesktop(window.innerWidth >= 768);
      };
      handleResize();
      window.addEventListener('resize', handleResize);
      return () => window.removeEventListener('resize', handleResize);
    }, []);

    const gridStyle = React.useMemo(() => {
      if (activeIndex === null) return {};

      if (isDesktop) {
        const columns = items
          .map((_, index) => (index === activeIndex ? '5fr' : '1fr'))
          .join(' ');
        return { gridTemplateColumns: columns };
      } else {
        const rows = items
          .map((_, index) => (index === activeIndex ? '5fr' : '1fr'))
          .join(' ');
        return { gridTemplateRows: rows };
      }
    }, [activeIndex, items, isDesktop]);

    const handleInteraction = (index: number) => {
      setActiveIndex(index);
    };

    return (
      <ul
        className={cn(
          'w-full max-w-5xl gap-2 grid h-[380px] md:h-[420px] transition-[grid-template-columns,grid-template-rows] duration-500 ease-out select-none',
          className
        )}
        style={{
          ...gridStyle,
          ...(isDesktop ? { gridTemplateRows: '1fr' } : { gridTemplateColumns: '1fr' }),
        }}
        ref={ref}
        {...props}
      >
        {items.map((item, index) => (
          <li
            key={item.id}
            className={cn(
              'group relative cursor-pointer overflow-hidden rounded-xl border border-neutral-800 bg-neutral-900 text-white shadow-lg md:min-w-[70px] min-h-0 min-w-0 transition-all duration-300'
            )}
            onMouseEnter={() => handleInteraction(index)}
            onFocus={() => handleInteraction(index)}
            onClick={() => handleInteraction(index)}
            tabIndex={0}
            data-active={activeIndex === index}
          >
            <img
              src={item.imgSrc}
              alt={item.title}
              className="absolute inset-0 h-full w-full object-cover transition-all duration-500 ease-out group-data-[active=true]:scale-105 group-data-[active=true]:grayscale-0 scale-100 grayscale-[40%]"
            />
            <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-black/40 to-transparent" />

            <article className="absolute inset-0 flex flex-col justify-end gap-2 p-4 z-10">
              <h3 className="hidden origin-left rotate-90 text-xs font-semibold uppercase tracking-wider text-white/80 opacity-100 transition-all duration-300 ease-out md:block group-data-[active=true]:opacity-0">
                {item.title}
              </h3>

              <div className="text-amber-400 opacity-0 transition-all duration-300 delay-75 ease-out group-data-[active=true]:opacity-100">
                {item.icon}
              </div>

              <h3 className="text-lg font-bold text-white opacity-0 transition-all duration-300 delay-150 ease-out group-data-[active=true]:opacity-100">
                {item.title}
              </h3>

              <p className="w-full max-w-xs text-xs text-neutral-300 opacity-0 transition-all duration-300 delay-200 ease-out group-data-[active=true]:opacity-100 line-clamp-3">
                {item.description}
              </p>
            </article>
          </li>
        ))}
      </ul>
    );
  }
);

ExpandingCards.displayName = 'ExpandingCards';

