            )}

            {isActive && (
              <motion.div
                layoutId="active-tab-indicator"
                className="absolute inset-0 -z-10 rounded-lg border border-slate-700/80 bg-slate-800/90 shadow-sm"
                transition={{ type: 'spring', bounce: 0.18, duration: 0.45 }}
              />
            )}
          </button>
        );
      })}
    </div>
  );
}

